        public static Image Get(string slug)
        {
            if (string.IsNullOrEmpty(slug)) return null;
            Image img;
            if (cache.TryGetValue(slug, out img)) return img;
            string b64;
            if (!data.TryGetValue(slug, out b64)) return null;
            try
            {
                byte[] bytes = Convert.FromBase64String(b64);
                using (MemoryStream ms = new MemoryStream(bytes)) img = Image.FromStream(ms);
                cache[slug] = img;
                return img;
            }
            catch { return null; }
        }
    }
